<?php require_once __DIR__.'/includes/config.php';$app=null;if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$s=$pdo->prepare('SELECT reference_no,loan_type,amount,status,created_at,updated_at FROM applications WHERE reference_no=?');$s->execute([strtoupper(trim($_POST['reference']??''))]);$app=$s->fetch();}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Track | Ladle Loan</title><link rel="stylesheet" href="assets/style.css"></head><body><div class="form-wrap"><form class="form-card" method="post"><a href="index.php">← Ladle Loan</a><h1>Track application</h1><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Reference number<input name="reference" placeholder="LL-XXXXXXXX" required></label><button class="btn">Check status</button><?php if($_SERVER['REQUEST_METHOD']==='POST'):?><?php if($app):?><div class="notice success">Status: <b><?=e($app['status'])?></b><br><?=e($app['loan_type'])?> · ₹<?=number_format((float)$app['amount'],2)?></div><?php else:?><div class="notice error">No application found for that reference.</div><?php endif;?><?php endif;?></form></div></body></html>